import { readFileSync } from "node:fs";

function parseJson(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

const input = readFileSync(0, "utf8");
const config = parseJson(input);

if (
  typeof config === "object" &&
  config !== null &&
  "port" in config &&
  typeof config.port === "number"
) {
  console.log(`port: ${config.port}`);
} else {
  console.log("port: 3000 (default)");
}

steps.body:
`never` is the type with no values at all. A function whose return type is `never` never returns normally, usually because it always throws. Since it never produces a value, a call to it fits wherever a value is expected, which makes it a neat way to stop on bad data:

```typescript
function fail(message: string): never {
  throw new Error(message);
}
const names = ["Ada", "Grace"];
const first = names[0] ?? fail("no names");
//    ^? const first: string
console.log(first.toUpperCase()); // ADA
```

`names[0]` is `string | undefined`, and `?? fail(...)` takes the `undefined` away, so `first` is a plain `string`.

`never` also appears when narrowing runs out of options. Once a `string | number` has been checked for both, nothing is left, so its type is `never`. Assigning it to a `never` variable there compiles only while every case is handled.

examples.code:
function fail(message: string): never {
  throw new Error(message);
}

type Config = { host: string; port?: number };

function address(config: Config): string {
  const port = config.port ?? fail(`no port for ${config.host}`);
  //    ^? const port: number
  return `${config.host}:${port}`;
}

console.log(address({ host: "localhost", port: 8080 }));
try {
  console.log(address({ host: "db.internal" }));
} catch (err) {
  console.log(err instanceof Error ? err.message : String(err));
}

function describe(x: string | number): string {
  if (typeof x === "string") {
    return `text "${x}"`;
  } else if (typeof x === "number") {
    return `number ${x}`;
  } else {
    const impossible: never = x;
    //                        ^? (parameter) x: never
    return impossible;
  }
}

console.log(describe("hi"));
console.log(describe(42));

examples.explanation:
The first two branches handle every member of `string | number`, so in the `else`, `x` is `never`, and assigning it to a `never` variable compiles. Now add `boolean` to the parameter without adding a branch, and that line stops compiling:

```typescript error
function describe(x: string | number | boolean): string {
  if (typeof x === "string") {
    return `text "${x}"`;
  } else if (typeof x === "number") {
    return `number ${x}`;
  } else {
    const impossible: never = x;
    return impossible;
  }
}

console.log(describe(true));
```

TS2322 says a `boolean` can't be a `never`, which points you at the case you forgot before anything runs.

