function fail(message: string): never {
  throw new Error(message);
}

export function requirePositive(n: number, label: string): number {
  if (n > 0) {
    return n;
  }
  return fail(`${label} must be positive`);
}

try {
  console.log(`quantity: ${requirePositive(3, "quantity")}`);
  console.log(`price: ${requirePositive(12.5, "price")}`);
  console.log(`discount: ${requirePositive(0, "discount")}`);
} catch (err) {
  console.log(err instanceof Error ? err.message : String(err));
}
